Outcome<SourceRef> finalize_state_need_task_in_candidate(CommonStore&common,TaskState&tasks,const StableId&id,const std::optional<SourceRef>&report,StateTaskSourceRead&sources,const WorldMoment&now){
 auto valid=current(common,now);if(!valid.ok)return {false,{},valid.error};auto*c=tasks.state_need_tasks?tasks.state_need_tasks->contracts.find(id):nullptr;if(!c||!c->closing_cause||!c->closing_source)return fail<SourceRef>("StateTaskNotSettling",id);if(c->settlement_source)return {true,*c->settlement_source,{}};if(report){valid=sources.validate_report_receipt(*c,*report);if(!valid.ok)return {false,{},valid.error};if(c->report_receipt&&!same(*c->report_receipt,*report))return fail<SourceRef>("StateTaskReportConflict",id);c->report_receipt=report;}const bool fulfilled=*c->closing_cause==StateClaimSettlementCause::fulfilled;if(fulfilled&&(!c->contribution_id||(c->report_required&&!c->report_receipt)))return fail<SourceRef>("StateTaskReportRequired",id);if(c->report_receipt){valid=sources.validate_report_receipt(*c,*c->report_receipt);if(!valid.ok)return {false,{},valid.error};}auto charges=sources.supplied_service_charges(*c);if(!charges.ok)return {false,{},charges.error};if(charges.value.actual_fee<0||charges.value.actual_fee>c->money.maximum_service_fee||(charges.value.actual_fee>0&&charges.value.original_sources.empty()))return fail<SourceRef>("StateTaskFeeSourceMismatch",id,ErrorKind::internal);std::set<StableId>charge_keys;for(const auto&s:charges.value.original_sources)if(!ref(s)||!charge_keys.insert(s.domain+":"+s.kind+":"+s.id).second)return fail<SourceRef>("DuplicateStateTaskServiceCharge",id,ErrorKind::internal);
 const auto*wallet=common.wallet(c->escrow_wallet_id);Integer total=0;if(__builtin_add_overflow(c->money.maximum_service_fee,c->money.success_reward,&total)||!wallet||wallet->owner.kind!=Owner::Kind::task||wallet->owner.id!=c->task_id||wallet->balance!=total)return fail<SourceRef>("StateTaskEscrowMismatch",id,ErrorKind::internal);const Integer reward=fulfilled?c->money.success_reward:0,fee=charges.value.actual_fee;ResourceRecipe recipe;if(total)recipe.operations.push_back(SetReservation{c->escrow_wallet_id,{ReservationRef::Kind::contract,c->id},0,true});if(fee+reward)recipe.operations.push_back(WalletDelta{c->money.payee_wallet_id,fee+reward,false});if(c->money.maximum_service_fee-fee)recipe.operations.push_back(WalletDelta{c->money.funding_wallet_id,c->money.maximum_service_fee-fee,false});if(c->money.success_reward-reward)recipe.operations.push_back(WalletDelta{c->money.reward_wallet_id,c->money.success_reward-reward,false});if(total)recipe.operations.push_back(WalletDelta{c->escrow_wallet_id,-total,false});valid=common.apply_resources(recipe);if(!valid.ok)return {false,{},valid.error};auto settlement=common.next_id("state_task_settled");if(!settlement.ok)return {false,{},settlement.error};StateTaskSettlement settled{settlement.value,c->id,*c->closing_cause,charges.value.original_sources,fee,reward,c->money.maximum_service_fee-fee,c->money.success_reward-reward,now};tasks.state_need_tasks->settlements.insert(settlement.value,std::move(settled));valid=common.append_fact({settlement.value,"state_task_settled","tasks"});if(!valid.ok)return {false,{},valid.error};c->settlement_source=SourceRef{"tasks","state_task_settled",settlement.value};c->phase=StateTaskContractPhase::closed;auto*task=tasks.tasks.find(c->task_id);if(!task)return fail<SourceRef>("StateTaskRecordMissing",id,ErrorKind::internal);task->settlement_id=settlement.value;task->reported_tick=common.tick();task->status=fulfilled?"success":(*c->closing_cause==StateClaimSettlementCause::claim_released||*c->closing_cause==StateClaimSettlementCause::withdrawn?"cancelled":"failed");task->late=false;return {true,*c->settlement_source,{}};
}
Outcome<WorldMoment> read_state_need_task_source_moment(const CommonStore&common,const TaskState&tasks,const SourceRef&s,Integer schema){if(s.domain!="tasks"||schema!=1||!tasks.state_need_tasks)return fail<WorldMoment>("UnsupportedStateTaskSource",s.id,ErrorKind::unsupported_capability);auto valid=header(common,s.id,s.kind.c_str());if(!valid.ok)return {false,{},valid.error};const auto&state=*tasks.state_need_tasks;if(s.kind=="state_task_accepted"){for(const auto&row:state.contracts.rows())if(row.second.acceptance_id==s.id)return {true,row.second.accepted_at,{}};}else if(s.kind=="state_task_closing"){const auto*v=state.closures.find(s.id);if(v)return {true,v->closed_at,{}};}else if(s.kind=="state_task_settled"){const auto*v=state.settlements.find(s.id);if(v)return {true,v->settled_at,{}};}return fail<WorldMoment>("StateTaskSourceMissing",s.id,ErrorKind::internal);}
Status validate_state_need_tasks(const CommonStore&common,const TaskState&tasks,const AffairsState&affairs,const StateTaskSourceRead&sources){if(!tasks.state_need_tasks)return common_success();if(!affairs.state_needs)return common_failure("StateNeedDomainMissing");const auto&state=*tasks.state_need_tasks;std::set<StableId>task_ids,accepted_ids,claim_ids,used_contributions,settled_ids,closed_ids;for(const auto&row:state.offers.rows()){if(row.first!=row.second.offer_ref.id)return common_failure("InvalidStateNeedOfferKey",row.first);auto valid=sources.validate_offer_disclosure(row.second);if(!valid.ok)return valid;}
 for(const auto&row:state.contracts.rows()){const auto&c=row.second;const auto*t=tasks.tasks.find(c.task_id);const auto*offer=state.offers.find(c.offer_id);const auto*claim=affairs.state_needs->claims.find(c.objective.claim_id);if(row.first!=c.id||!t||!offer||!claim||!task_ids.insert(c.task_id).second||!accepted_ids.insert(c.acceptance_id).second||!claim_ids.insert(c.objective.claim_id).second||t->contract_id||t->assignee!=c.executor_actor_id||t->budget_wallet_id!=c.escrow_wallet_id||c.claim_until_tick<=c.accepted_at.half_day_tick||c.accepted_goal_revision<1||static_cast<Integer>(c.phase)<0||static_cast<Integer>(c.phase)>2)return common_failure("InvalidStateTaskContract",row.first);if(!same_money(c.money,offer->fee_reward_terms)||!same_objective(c.objective,offer->objective)||c.completion_gate.tick!=offer->completion_gate.tick||c.completion_gate.inclusive!=offer->completion_gate.inclusive||c.cancel_policy!=offer->cancel_policy||!same(c.report_recipient,offer->report_recipient)||c.report_required!=offer->report_required||t->offer_id!=c.offer_id||t->accepted_tick!=c.accepted_at.half_day_tick||t->deadline_tick!=c.completion_gate.tick||!t->accepted_at)return common_failure("StateTaskFrozenTermsMismatch",row.first);auto moment=compare_world_moments(*t->accepted_at,c.accepted_at);if(!moment.ok)return {false,{},moment.error};if(moment.value)return common_failure("StateTaskAcceptanceMomentMismatch",row.first);auto valid=escrow(common,c);if(!valid.ok)return valid;valid=claim_binding(c,*claim);if(!valid.ok)return valid;valid=header(common,c.acceptance_id,"state_task_accepted");if(!valid.ok)return valid;valid=sources.validate_frozen_terms(c.money,c.assignee,c.executor_actor_id);if(!valid.ok)return valid;if(c.contribution_id){const auto*p=state.predicate_contributions.find(*c.contribution_id);if(!p||p->contract_id!=c.id||p->claim_id!=claim->claim_id||p->need_id!=claim->need_ref.need_id||p->episode!=claim->need_ref.episode||p->criterion!=c.objective.criterion||!used_contributions.insert(p->id).second)return common_failure("StatePredicateContributionMismatch",row.first);auto actual=proof(c,p->satisfaction_ref,sources);if(!actual.ok)return {false,{},actual.error};if(!actual.value||!same(actual.value->actual_contribution_ref,p->actual_contribution_ref)||!same(actual.value->applied_result_ref,p->applied_result_ref))return common_failure("StatePredicateProofMismatch",row.first);}
  if(c.phase==StateTaskContractPhase::active){if(c.closing_source||c.closing_cause||c.settlement_source||c.contribution_id)return common_failure("ActiveStateTaskHasClosure",row.first);}else{const auto*close=c.closing_source?state.closures.find(c.closing_source->id):nullptr;if(!close||!c.closing_cause||close->contract_id!=c.id||close->cause!=*c.closing_cause||!closed_ids.insert(close->id).second)return common_failure("StateTaskClosingMismatch",row.first);valid=header(common,close->id,"state_task_closing");if(!valid.ok)return valid;if(close->cause!=StateClaimSettlementCause::fulfilled){valid=sources.validate_service_stop(c,close->cause,close->actual_service_stop_ref);if(!valid.ok)return valid;}}
  if(c.report_receipt){valid=sources.validate_report_receipt(c,*c.report_receipt);if(!valid.ok)return valid;}const auto*wallet=common.wallet(c.escrow_wallet_id);if(!wallet||wallet->owner.kind!=Owner::Kind::task||wallet->owner.id!=c.task_id)return common_failure("StateTaskEscrowMismatch",row.first);if(c.phase==StateTaskContractPhase::closed){const auto*settled=c.settlement_source?state.settlements.find(c.settlement_source->id):nullptr;if(!settled||settled->contract_id!=c.id||!settled_ids.insert(settled->id).second||t->settlement_id!=settled->id||wallet->balance!=0||!wallet->reserved.empty()||settled->paid_service_fee<0||settled->refunded_service_fee<0||settled->paid_success_reward<0||settled->refunded_reward<0||settled->paid_service_fee>c.money.maximum_service_fee||settled->refunded_service_fee!=c.money.maximum_service_fee-settled->paid_service_fee||settled->paid_success_reward>c.money.success_reward||settled->refunded_reward!=c.money.success_reward-settled->paid_success_reward||((settled->cause==StateClaimSettlementCause::fulfilled)!=c.contribution_id.has_value())||(settled->cause!=StateClaimSettlementCause::fulfilled&&settled->paid_success_reward!=0))return common_failure("StateTaskSettlementMismatch",row.first);valid=header(common,settled->id,"state_task_settled");if(!valid.ok)return valid;auto charges=sources.supplied_service_charges(c);if(!charges.ok)return {false,{},charges.error};if(charges.value.actual_fee!=settled->paid_service_fee||charges.value.original_sources.size()!=settled->service_charge_sources.size())return common_failure("StateTaskFeeSourceMismatch",row.first);for(std::size_t i=0;i<charges.value.original_sources.size();++i)if(!same(charges.value.original_sources[i],settled->service_charge_sources[i]))return common_failure("StateTaskFeeSourceMismatch",row.first);}
 }
 if(used_contributions.size()!=state.predicate_contributions.size()||settled_ids.size()!=state.settlements.size()||closed_ids.size()!=state.closures.size())return common_failure("OrphanStateTaskSource");return common_success();
}
